 <?php $__env->startSection('content'); ?><div class="top"><div><h1>User Management</h1><div class="muted">Manage authorized Owner and Sales Clerk accounts</div></div><div class="who">Owner</div></div><div class="toolbar"><a class="btn primary" href="<?php echo e(route('users.create')); ?>">+ Add User</a></div><table class="table"><thead><tr><th>Username</th><th>First Name</th><th>Last Name</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php $__currentLoopData = $users; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $u): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><?php echo e($u->username); ?></td><td><?php echo e($u->first_name); ?></td><td><?php echo e($u->last_name); ?></td><td><?php echo e($u->role==='OWNER'?'Owner':'Sales Clerk'); ?></td><td><?php echo e($u->is_active?'Active':'Inactive'); ?></td><td><div class="actions"><a class="btn light small" href="<?php echo e(route('users.edit',$u)); ?>">Edit</a><?php if($u->user_id!==auth()->id()): ?><form method="POST" action="<?php echo e(route('users.toggle',$u)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><button class="btn secondary small"><?php echo e($u->is_active?'Deactivate':'Activate'); ?></button></form><?php endif; ?></div></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table><div class="note">Passwords are never displayed in user lists.</div><?php $__env->stopSection(); ?>

